import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface rageClickTintLogicValues {
    intensity: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface rageClickTintLogicActions {
    coolDown: () => {
        value: true
    }
    rageClick: () => {
        value: true
    }
}

export type rageClickTintLogicType = MakeLogicType<rageClickTintLogicValues, rageClickTintLogicActions>

export const rageClickTintLogic = kea<rageClickTintLogicType>([
    path(['layout', 'rageClickTintLogic']),
    actions({
        rageClick: true,
        coolDown: true,
    }),
    reducers({
        intensity: [
            0,
            {
                rageClick: (state) => Math.min(state + 2, 12),
                coolDown: (state) => Math.max(state - 1, 0),
            },
        ],
    }),
    listeners(({ actions, values, cache }) => ({
        rageClick: () => {
            const coolDownAt = Date.now() + 5000
            cache.disposables.add(
                () => {
                    const timer = window.setInterval(() => {
                        if (Date.now() >= coolDownAt) {
                            actions.coolDown()
                        }
                    }, 1000)
                    return () => window.clearInterval(timer)
                },
                'coolDown',
                { pauseOnPageHidden: false }
            )
        },
        coolDown: () => {
            if (values.intensity === 0) {
                cache.disposables.dispose('coolDown')
            }
        },
    })),
    afterMount(({ actions, cache }) => {
        cache.disposables.add(() =>
            posthog.on('eventCaptured', (event) => {
                if (event.event === '$rageclick') {
                    actions.rageClick()
                }
            })
        )
    }),
])
